  // ==== DATA END ====

  var DEG = Math.PI / 180;
  function clamp(v, a, b) { return v < a ? a : (v > b ? b : v); }
  function vec(lat, lon, out, o) {
    var la = lat * DEG, lo = lon * DEG, c = Math.cos(la);
    out[o] = c * Math.sin(lo); out[o + 1] = Math.sin(la); out[o + 2] = c * Math.cos(lo);
  }

  // ---------- суша: равномерные точки + связи ----------
  function pointInPoly(poly, lon, lat) {
    var inside = false;
    for (var i = 0, j = poly.length - 1; i < poly.length; j = i++) {
      var xi = poly[i][0], yi = poly[i][1], xj = poly[j][0], yj = poly[j][1];
      if (((yi > lat) !== (yj > lat)) && (lon < (xj - xi) * (lat - yi) / (yj - yi) + xi)) inside = !inside;
    }
    return inside;
  }
  function bbox(poly) {
    var a = 999, b = -999, c = 999, d = -999;
    for (var i = 0; i < poly.length; i++) {
      if (poly[i][0] < a) a = poly[i][0]; if (poly[i][0] > b) b = poly[i][0];
      if (poly[i][1] < c) c = poly[i][1]; if (poly[i][1] > d) d = poly[i][1];
    }
    return [a, b, c, d];
  }
  var landPolys = [], holePolys = [], k;
  for (k in LAND) landPolys.push({ p: LAND[k], b: bbox(LAND[k]) });
  for (k in HOLES) if (HOLES[k].length) holePolys.push({ p: HOLES[k], b: bbox(HOLES[k]) });
  function inList(list, lon, lat) {
    for (var i = 0; i < list.length; i++) {
      var b = list[i].b;
      if (lon >= b[0] && lon <= b[1] && lat >= b[2] && lat <= b[3] && pointInPoly(list[i].p, lon, lat)) return true;
    }
    return false;
  }

  var NF = 9000, GA = Math.PI * (3 - Math.sqrt(5)), LP = [], i, j;
  for (i = 0; i < NF; i++) {
    var yy = 1 - 2 * (i + 0.5) / NF, rr = Math.sqrt(1 - yy * yy), th = GA * i;
    var lat = Math.asin(yy) / DEG, lon = ((Math.atan2(Math.sin(th) * rr, Math.cos(th) * rr) / DEG) + 540) % 360 - 180;
    if (inList(landPolys, lon, lat) && !inList(holePolys, lon, lat)) LP.push([Math.cos(th) * rr, yy, Math.sin(th) * rr, lat, lon]);
  }
  // Fibonacci-координаты (x,z) → переводим в схему «lon от z» для единообразия
  var NL = LP.length, LV = new Float32Array(NL * 3);
  for (i = 0; i < NL; i++) vec(LP[i][3], LP[i][4], LV, i * 3);
  var d0 = Math.sqrt(4 * Math.PI / NF), thr2 = Math.pow(d0 * 1.55, 2), LE = [];
  for (i = 0; i < NL; i++) {
    for (j = i + 1; j < NL; j++) {
      var dx = LV[i * 3] - LV[j * 3];
      if (dx > d0 * 1.6 || dx < -d0 * 1.6) continue;
      var dy = LV[i * 3 + 1] - LV[j * 3 + 1], dz = LV[i * 3 + 2] - LV[j * 3 + 2];
      if (dx * dx + dy * dy + dz * dz < thr2) LE.push(i, j);
    }
  }

  // ---------- береговые линии (с подразбиением по дуге) ----------
  function ringToVecs(poly) {
    var out = [], n = poly.length;
    for (var a = 0; a < n; a++) {
      var p = poly[a], q = poly[(a + 1) % n];
      var dl = q[0] - p[0], dla = q[1] - p[1];
      if (Math.abs(dl) > 180) continue;                    // не тянем линии через линию перемены дат
      var steps = Math.max(1, Math.ceil(Math.max(Math.abs(dl), Math.abs(dla)) / 2.2));
      for (var s = 0; s < steps; s++) {
        var v = [0, 0, 0]; vec(p[1] + dla * s / steps, p[0] + dl * s / steps, v, 0);
        out.push(v[0], v[1], v[2]);
      }
    }
    return new Float32Array(out);
  }
  var COAST = [];
  for (k in LAND) { if (k === 'antarctica') continue; COAST.push(ringToVecs(LAND[k])); }
  for (k in HOLES) if (HOLES[k].length) COAST.push(ringToVecs(HOLES[k]));

  // ---------- сетка широт/долгот ----------
  var GRAT = [];
  (function () {
    var la, lo, v = [0, 0, 0];
    for (lo = -180; lo < 180; lo += 30) {
      var m = []; for (la = -84; la <= 84; la += 4) { vec(la, lo, v, 0); m.push(v[0], v[1], v[2]); }
      GRAT.push(new Float32Array(m));
    }
    for (la = -60; la <= 60; la += 30) {
      var p = []; for (lo = -180; lo <= 180; lo += 4) { vec(la, lo, v, 0); p.push(v[0], v[1], v[2]); }
      GRAT.push(new Float32Array(p));
    }
  })();

  // ---------- «сеть» над поверхностью ----------
  var NS = 130, SV = new Float32Array(NS * 3), SE = [], seed = 12345;
