  // ---------- рисование ----------
  var m = { cl: 1, sl: 0, ct: 1, st: 0 };
  function setRot() { m.cl = Math.cos(rotLon); m.sl = Math.sin(rotLon); m.ct = Math.cos(tilt); m.st = Math.sin(tilt); }
