    ctx.lineWidth = 1; ctx.strokeStyle = 'rgba(90,150,255,0.10)';
    strokeRings(GRAT, 0.1, 1, 'rgba(90,150,255,0.10)');

    // проекция точек суши
    for (i = 0; i < NL; i++) {
      rot(LV[i * 3], LV[i * 3 + 1], LV[i * 3 + 2], T);
      LX[i] = cx + T[0] * R; LY[i] = cy - T[1] * R; LZ[i] = T[2];
    }
    // связи по земле — 3 корзины глубины
    var bk = [[], [], []], e;
    for (e = 0; e < LE.length; e += 2) {
      var a = LE[e], b = LE[e + 1], z = (LZ[a] + LZ[b]) / 2;
      if (LZ[a] < 0.04 || LZ[b] < 0.04) continue;
      bk[z < 0.35 ? 0 : (z < 0.7 ? 1 : 2)].push(a, b);
    }
    var la = [0.10, 0.17, 0.25];
    for (j = 0; j < 3; j++) {
      ctx.strokeStyle = 'rgba(110,190,255,' + la[j] + ')'; ctx.lineWidth = 1; ctx.beginPath();
      for (e = 0; e < bk[j].length; e += 2) { ctx.moveTo(LX[bk[j][e]], LY[bk[j][e]]); ctx.lineTo(LX[bk[j][e + 1]], LY[bk[j][e + 1]]); }
      ctx.stroke();
    }
    // точки суши
    var dots = [[], [], []];
    for (i = 0; i < NL; i++) if (LZ[i] > 0.04) dots[LZ[i] < 0.35 ? 0 : (LZ[i] < 0.7 ? 1 : 2)].push(i);
    var da = [0.35, 0.6, 0.85];
    for (j = 0; j < 3; j++) {
      ctx.fillStyle = 'rgba(150,215,255,' + da[j] + ')';
      for (e = 0; e < dots[j].length; e++) ctx.fillRect(LX[dots[j][e]] - 0.9, LY[dots[j][e]] - 0.9, 1.8, 1.8);
    }
    // береговая линия: мягкое свечение + тонкая яркая линия
    strokeRings(COAST, 0.2, 4, 'rgba(60,150,255,0.16)');
    strokeRings(COAST, 0.9, 1.1, 'rgba(140,230,255,0.85)');

    // сеть над поверхностью (видна и над горизонтом)
    for (i = 0; i < NS; i++) {
      rot(SV[i * 3], SV[i * 3 + 1], SV[i * 3 + 2], T);
      SHX[i] = cx + T[0] * R; SHY[i] = cy - T[1] * R; SHZ[i] = (T[2] > 0 || T[0] * T[0] + T[1] * T[1] > 1) ? 1 : 0;
    }
    ctx.strokeStyle = 'rgba(130,190,255,0.16)'; ctx.lineWidth = 1; ctx.beginPath();
    for (e = 0; e < SE.length; e += 2) {
      if (SHZ[SE[e]] && SHZ[SE[e + 1]] && SHY[SE[e]] < cy + 2 && SHY[SE[e + 1]] < cy + 2) { ctx.moveTo(SHX[SE[e]], SHY[SE[e]]); ctx.lineTo(SHX[SE[e + 1]], SHY[SE[e + 1]]); }
    }
